import {clamp,options} from './editor-core.js';
import {isContainer} from './catalog.js';
export function desktop(p){return {mode:'solid',gradientEnd:'#34204d',angle:135,image:'',video:'',videoMuted:true,videoRate:1,fit:'cover',position:'center',showText:true,text:'MAKE SPACE\nFOR YOURSELF',textColor:'#647b80',...p.canvas.desktop};}
export function appearance(e){return {opacity:1,blur:0,shadow:0,borderWidth:0,borderColor:'#cba6f7',font:'sans-serif',fontAsset:'',...e.appearance};}
export function constrain(p,e){const parent=p.elements.find(n=>n.id===e.parentId)||p.canvas,min=e.type==='shape'?2:20;e.width=clamp(e.width,min,parent.width);e.height=clamp(e.height,min,parent.height);e.x=clamp(e.x,0,parent.width-e.width);e.y=clamp(e.y,0,parent.height-e.height);}
export function clampAll(p){for(const e of p.elements.filter(n=>!n.parentId))constrain(p,e);for(const e of p.elements.filter(n=>n.parentId))constrain(p,e);}
export function changeSize(p,width,height){const old={...p.canvas};p.canvas.width=width;p.canvas.height=height;for(const e of p.elements.filter(n=>!n.parentId)){const oldWidth=e.width,oldHeight=e.height;const h=e.anchorX||'scale',v=e.anchorY||'scale';if(h==='right')e.x+=width-old.width;else if(h==='center')e.x+=(width-old.width)/2;else if(h==='stretch')e.width+=width-old.width;else if(h==='scale'){e.x*=width/old.width;e.width*=width/old.width;}if(v==='bottom')e.y+=height-old.height;else if(v==='center')e.y+=(height-old.height)/2;else if(v==='stretch')e.height+=height-old.height;else if(v==='scale'){e.y*=height/old.height;e.height*=height/old.height;}for(const c of p.elements.filter(n=>n.parentId===e.id)){c.x*=e.width/oldWidth;c.y*=e.height/oldHeight;}}clampAll(p);}
export function snap(p,e,enabled=true){constrain(p,e);if(!enabled)return [];const parent=p.elements.find(n=>n.id===e.parentId)||p.canvas;const guides=[];for(const axis of ['x','y']){const size=axis==='x'?'width':'height';const targets=[0,parent[size]/2,parent[size],...p.elements.filter(n=>n.id!==e.id&&n.parentId===e.parentId).flatMap(n=>[n[axis],n[axis]+n[size]/2,n[axis]+n[size]])];let best=null;for(const t of targets)for(const offset of [0,e[size]/2,e[size]]){const diff=t-e[axis]-offset;if(Math.abs(diff)<=6&&(!best||Math.abs(diff)<Math.abs(best.diff)))best={diff,t};}if(best){e[axis]+=best.diff;guides.push({axis,value:best.t});}}constrain(p,e);return guides;}
export function arrange(p,ids,action){const nodes=p.elements.filter(e=>ids.includes(e.id));if(!nodes.length)return;if(new Set(nodes.map(e=>e.parentId||'')).size!==1)throw Error('Select layers in the same container');const parent=p.elements.find(e=>e.id===nodes[0].parentId)||p.canvas;if(action.startsWith('distribute')){if(nodes.length<3)throw Error('Select at least three layers');const horizontal=action.endsWith('x'),axis=horizontal?'x':'y',size=horizontal?'width':'height';nodes.sort((a,b)=>a[axis]-b[axis]);const start=nodes[0][axis],end=nodes.at(-1)[axis]+nodes.at(-1)[size],gap=(end-start-nodes.reduce((n,e)=>n+e[size],0))/(nodes.length-1);if(gap<0)throw Error('Not enough space to distribute without overlap');let pos=start;for(const e of nodes){e[axis]=pos;pos+=e[size]+gap;}}
else for(const e of nodes){if(action==='left')e.x=0;if(action==='center')e.x=(parent.width-e.width)/2;if(action==='right')e.x=parent.width-e.width;if(action==='top')e.y=0;if(action==='middle')e.y=(parent.height-e.height)/2;if(action==='bottom')e.y=parent.height-e.height;}for(const e of nodes)constrain(p,e);}
export function autoLayout(p,parent){const kids=p.elements.filter(n=>n.parentId===parent.id),o=options(parent);let pos=o.padding;for(const e of kids){e.y=Math.max(0,(parent.height-e.height)/2);e.x=pos;pos+=e.width+o.gap;constrain(p,e);}return pos-o.gap+o.padding>parent.width;}
export function rgba(hex,alpha){return `rgba(${parseInt(hex.slice(1,3),16)},${parseInt(hex.slice(3,5),16)},${parseInt(hex.slice(5,7),16)},${alpha})`;}
